using FluentAssertions;
using NetworkOptimizer.Monitoring.WanFlood;
using Xunit;

namespace NetworkOptimizer.Monitoring.Tests.WanFlood;

public class WanFloodSaveParsersTests
{
    private const string FilterSave =
        "# Generated by iptables-save v1.8.7 on Sun Oct 18 14:00:00 2026\n" +
        "*filter\n" +
        ":UBIOS_WAN_LOCAL_USER - [0:0]\n" +
        "[120:9000] -A UBIOS_WAN_LOCAL_USER -m conntrack --ctstate RELATED,ESTABLISHED -j RETURN\n" +
        "[10:600] -A UBIOS_WAN_LOCAL_USER -m conntrack --ctstate INVALID -j DROP\n" +
        "[4380000:6240000000] -A UBIOS_WAN_LOCAL_USER -m comment --comment 00000001097364144127 -j DROP\n" +
        "[7:420] -A UBIOS_WAN_LOCAL_USER_X -j DROP\n" +
        "COMMIT\n";

    [Fact]
    public void SaveCounters_OneChainInOrder()
    {
        var rules = WanFloodParsers.ParseSaveCounters(FilterSave, "UBIOS_WAN_LOCAL_USER");
        rules.Should().HaveCount(3);
        rules.Select(r => r.Target).Should().Equal("RETURN", "DROP", "DROP");
        WanFloodParsers.LastDropPackets(rules).Should().Be(4_380_000);
        WanFloodParsers.DropPackets(rules).Should().Be(4_380_010);
    }

    [Fact]
    public void SaveCounters_AChainPrefixDoesNotMatchALongerName()
    {
        // UBIOS_WAN_LOCAL_USER_X must not be counted as UBIOS_WAN_LOCAL_USER.
        WanFloodParsers.ParseSaveCounters(FilterSave, "UBIOS_WAN_LOCAL_USER").Should().NotContain(r => r.Packets == 7);
    }

    [Fact]
    public void SaveCounters_MatchOnlyRulesHaveNoTarget()
    {
        const string mangle = "*mangle\n:NETOPT_FLOOD - [0:0]\n" +
            "[5:300] -A NETOPT_FLOOD -p udp -m hashlimit --hashlimit-above 500/sec --hashlimit-name nasu_abc123\n" +
            "[9:540] -A NETOPT_FLOOD -p udp -m hashlimit --hashlimit-above 2000/sec --hashlimit-name nus_def456 -j DROP\n";
        var rules = WanFloodParsers.ParseSaveCounters(mangle, "NETOPT_FLOOD");
        rules.Select(r => r.Target).Should().Equal("", "DROP");
        WanFloodParsers.DropPackets(rules).Should().Be(9);
    }

    [Fact]
    public void ShaperDrops_LeafQdiscsOnly()
    {
        const string text =
            "qdisc htb 1: root refcnt 2 r2q 10 default 0x2 direct_packets_stat 0 direct_qlen 1000\n" +
            " Sent 9000000 bytes 7000 pkt (dropped 147000, overlimits 0 requeues 0)\n" +
            "qdisc fq_codel 2: parent 1:2 limit 2000p flows 1024 quantum 1514 target 5ms interval 100ms\n" +
            " Sent 5000000 bytes 4000 pkt (dropped 100000, overlimits 0 requeues 0)\n" +
            "qdisc fq_codel 4: parent 1:4 limit 10240p flows 1024 quantum 1514 target 5ms interval 100ms\n" +
            " Sent 4000000 bytes 3000 pkt (dropped 47000, overlimits 0 requeues 0)\n";
        // The htb root's 147000 is the same drops again; only the fq_codel leaves count.
        WanFloodParsers.ParseLeafQdiscDrops(text).Should().Be(147000);
        WanFloodParsers.ParseLeafQdiscDrops("").Should().Be(0);
    }

    [Fact]
    public void ConntrackSessions_OnePassForEveryKey()
    {
        const string text =
            "ipv4     2 udp      17 29 src=203.0.113.5 dst=198.51.100.2 sport=40000 dport=51820 src=192.0.2.10 dst=203.0.113.5 sport=51820 dport=40000 [ASSURED] mark=0\n" +
            "ipv4     2 tcp      6 117 SYN_SENT src=203.0.113.9 dst=198.51.100.2 sport=50000 dport=443 [UNREPLIED] src=192.0.2.11 dst=203.0.113.9 sport=443 dport=50000 mark=0\n";
        var keys = new[]
        {
            ("203.0.113.5", "198.51.100.2", "udp", 51820),
            ("203.0.113.9", "198.51.100.2", "tcp", 443),
            ("203.0.113.6", "198.51.100.2", "udp", 51820),
        };
        var found = WanFloodParsers.ScanConntrackSessions(new StringReader(text), keys);
        found.Should().BeEquivalentTo(new[] { keys[0], keys[1] });
    }
}
